messages.content:
Write the application service of PayOrder.

Design:
{
 "context": "payments",
 "base_package": "com.bank.payments",
 "entities": [
  {
   "name": "PaymentOrder",
   "table": "payment_order",
   "legacy_table": "db_pagos..pg_orden",
   "key": [
    "orderNumber",
    "companyId"
   ],
   "fields": [
    {
     "name": "orderNumber",
     "type": "integer(32,signed)",
     "column": "order_number",
     "legacy": "ord_numero"
    },
    {
     "name": "companyId",
     "type": "integer(32,signed)",
     "column": "company_id",
     "legacy": "ord_empresa"
    },
    {
     "name": "status",
     "type": "text(fixed,1,iso8859-1)",
     "column": "status",
     "legacy": "ord_estado"
    },
    {
     "name": "paymentDate",
     "type": "timestamp(local)",
     "column": "payment_date",
     "legacy": "ord_fecha_pago"
    },
    {
     "name": "commission",
     "type": "decimal(19,4,signed)",
     "column": "commission",
     "legacy": "ord_comision"
    }
   ]
  },
  {
   "name": "CompanyTariff",
   "table": "company_tariff",
   "legacy_table": "db_admin..ad_tarifa_empresa",
   "key": [
    "companyId",
    "serviceCode"
   ],
   "fields": [
    {
     "name": "companyId",
     "type": "integer(32,signed)",
     "column": "company_id",
     "legacy": "tar_empresa"
    },
    {
     "name": "serviceCode",
     "type": "text(var,10,iso8859-1)",
     "column": "service_code",
     "legacy": "tar_servicio"
    },
    {
     "name": "tariffValue",
     "type": "decimal(19,4,signed)",
     "column": "tariff_value",
     "legacy": "tar_valor"
    },
    {
     "name": "separateCharge",
     "type": "text(fixed,1,iso8859-1)",
     "column": "separate_charge",
     "legacy": "tar_separada"
    }
   ]
  },
  {
   "name": "ServiceCatalog",
   "table": "service_catalog",
   "legacy_table": "db_admin..ad_servicio",
   "key": [
    "serviceCode"
   ],
   "fields": [
    {
     "name": "serviceCode",
     "type": "text(var,10,iso8859-1)",
     "column": "service_code",
     "legacy": "srv_codigo"
    },
    {
     "name": "defaultTariff",
     "type": "decimal(19,4,signed)",
     "column": "default_tariff",
     "legacy": "srv_tarifa"
    }
   ]
  },
  {
   "name": "Account",
   "table": "account",
   "legacy_table": "db_cuentas..ct_cuenta",
   "key": [
    "accountNumber",
    "accountType"
   ],
   "fields": [
    {
     "name": "accountNumber",
     "type": "text(fixed,10,iso8859-1)",
     "column": "account_number",
     "legacy": "cta_numero"
    },
    {
     "name": "accountType",
     "type": "text(fixed,3,iso8859-1)",
     "column": "account_type",
     "legacy": "cta_tipo"
    },
    {
     "name": "balance",
