   "name": "DebitResult",
   "table": null,
   "legacy_table": null,
   "key": [],
   "fields": [
    {
     "name": "movement",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "@o_secuencial"
    },
    {
     "name": "returnCode",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "return"
    }
   ]
  }
 ],
 "ports": [
  {
   "name": "OrderRepository",
   "entity": "PaymentOrder",
   "legacy_program": null,
   "methods": [
    {
     "name": "findByNumberAndCompany",
     "description": "Reads the order of a company (status).",
     "inputs": [
      {
       "name": "orderNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ord_numero"
      },
      {
       "name": "companyId",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ord_empresa"
      }
     ],
     "returns": "PaymentOrder",
     "legacy_output": null
    },
    {
     "name": "markPaid",
     "description": "Sets status 'A', payment date and commission on the order; returns the number of rows affected.",
     "inputs": [
      {
       "name": "orderNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ord_numero"
      },
      {
       "name": "companyId",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ord_empresa"
      },
      {
       "name": "status",
       "type": "text(fixed,1,iso8859-1)",
       "column": null,
       "legacy": "ord_estado"
      },
      {
       "name": "paymentDate",
       "type": "timestamp(local)",
       "column": null,
       "legacy": "ord_fecha_pago"
      },
      {
       "name": "commission",
       "type": "decimal(19,4,signed)",
       "column": null,
       "legacy": "ord_comision"
      }
     ],
     "returns": "int",
     "legacy_output": null
    }
   ]
  },
  {
   "name": "CompanyTariffRepository",
   "entity": "CompanyTariff",
   "legacy_program": null,
   "methods": [
    {
     "name": "findByCompanyAndService",
     "description": "Reads the tariff agreed for a company and service.",
     "inputs": [
      {
       "name": "companyId",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "tar_empresa"
      },
      {
       "name": "serviceCode",
       "type": "text(var,10,iso8859-1)",
       "column": null,
       "legacy": "tar_servicio"
      }
     ],
     "returns": "CompanyTariff",
     "legacy_output": null
    }
   ]
  },
  {
   "name": "ServiceRepository",
   "entity": "ServiceCatalog",
   "legacy_program": null,
   "methods": [
    {
     "name": "findByCode",
     "description": "Reads the service with its default tariff.",
     "inputs": [
      {
       "name": "serviceCode",
       "type": "text(var,10,iso8859-1)",
       "column": null,
       "legacy": "srv_codigo"
      }
     ],
     "returns": "ServiceCatalog",
     "legacy_output": null
    }
   ]
  },
  {
   "name": "AccountRepository",
   "entity": "Account",
   "legacy_program": null,
   "methods": [
    {
     "name": "findByNumberAndType",
     "description": "Reads the account balance.",
     "inputs": [
      {
       "name": "accountNumber",
       "type": "text(fixed,10,iso8859-1)",
       "column": null,
       "legacy": "cta_numero"
      },
      {
       "name": "accountType",
       "type": "text(fixed,3,iso8859-1)",
       "column": null,
       "legacy": "cta_tipo"
      }
     ],
     "returns": "Account",
     "legacy_output": null
    }
   ]
  },
  {
   "name": "DebitGateway",
   "entity": "DebitResult",
   "legacy_program": "db_cuentas..sp_debito",
   "methods": [
    {
     "name": "debit",
     "description": "Debits an account and returns the movement sequence and the return status of sp_debito.",
     "inputs": [
      {
       "name": "accountNumber",
       "type": "text(fixed,10,iso8859-1)",
       "column": null,
       "legacy": "@i_cuenta"
      },
      {
       "name": "accountType",
       "type": "text(fixed,3,iso8859-1)",
       "column": null,
       "legacy": "@i_tipo"
      },
      {
       "name": "amount",
       "type": "decimal(19,4,signed)",
       "column": null,
       "legacy": "@i_valor"
      },
      {
       "name": "reference",
       "type": "text(var,40,iso8859-1)",
       "column": null,
       "legacy": "@i_referencia"
      }
     ],
     "returns": "DebitResult",
     "legacy_output": null,
     "legacy_outputs": {
      "movement": "@o_secuencial",
      "returnCode": "return"
     }
    }
   ]
  }
 ],
 "use_cases": [
  {
   "name": "PayOrder",
   "description": "Pays a payment order: validates account type, order and funds, computes tariff, commission and total, debits the account (and the commission when charged separately), marks the order as paid and commits atomically.",
   "rules": [
    "RULE-001",
    "RULE-002",
    "RULE-003",
    "RULE-004",
    "RULE-005",
    "RULE-006",
    "RULE-007",
    "RULE-008",
    "RULE-009",
    "RULE-010",
    "RULE-011",
    "RULE-012",
    "RULE-013"
   ],
   "inputs": [
    {
     "name": "orderNumber",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "@i_orden"
    },
    {
     "name": "companyId",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "@i_empresa"
    },
    {
     "name": "serviceCode",
     "type": "text(var,10,iso8859-1)",
     "column": null,
     "legacy": "@i_servicio"
    },
    {
     "name": "accountType",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "@i_tipo_cuenta"
    },
    {
     "name": "accountNumber",
     "type": "text(fixed,10,iso8859-1)",
     "column": null,
     "legacy": "@i_cuenta"
    },
    {
     "name": "amount",
     "type": "decimal(19,4,signed)",
     "column": null,
     "legacy": "@i_valor"
    },
    {
     "name": "channel",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "@i_canal"
    },
    {
     "name": "processDate",
     "type": "timestamp(local)",
     "column": null,
     "legacy": "@i_fecha_proceso"
    }
   ],
   "outputs": [
    {
     "name": "movement",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "@o_movimiento"
    },
    {
     "name": "message",
     "type": "text(var,120,iso8859-1)",
     "column": null,
     "legacy": "@o_mensaje"
    }
   ],
   "errors": [
    {
     "code": "ACCOUNT_TYPE_NOT_ALLOWED",
     "legacy_code": "50001",
     "message": "TIPO DE CUENTA NO PERMITIDO"
    },
    {
     "code": "ORDER_NOT_FOUND",
     "legacy_code": "50002",
     "message": "ORDEN NO EXISTE"
    },
    {
     "code": "ORDER_NOT_PENDING",
     "legacy_code": "50003",
     "message": "ORDEN NO ESTA PENDIENTE"
    },
    {
     "code": "INSUFFICIENT_FUNDS",
     "legacy_code": "50004",
     "message": "FONDOS INSUFICIENTES"
    },
    {
     "code": "DEBIT_FAILED",
     "legacy_code": "50005",
     "message": "ERROR EN DEBITO"
    },
    {
     "code": "COMMISSION_FAILED",
     "legacy_code": "50006",
     "message": "ERROR EN COMISION"
    },
    {
     "code": "ORDER_UPDATE_FAILED",
     "legacy_code": "50007",
     "message": "ERROR ACTUALIZANDO ORDEN"
    }
   ],
   "ports": [
    "OrderRepository",
    "CompanyTariffRepository",
    "ServiceRepository",
    "AccountRepository",
    "DebitGateway"
   ],
   "http_method": "POST",
   "path": "/payment-orders/pay",
   "legacy_program": "dbo.sp_pago_orden",
   "unit_of_work": {
    "begins_at": 108,
    "commits_at": 161,
    "savepoints": [],
    "rollbacks": [
     {
      "legacy_line": 119,
      "outcome": "DEBIT_FAILED"
     },
     {
      "legacy_line": 136,
      "outcome": "COMMISSION_FAILED"
     },
     {
      "legacy_line": 155,
      "outcome": "ORDER_UPDATE_FAILED"
     }
    ]
   },
   "legacy_message": "@o_mensaje"
  }
 ],
 "decisions": [
  {
   "title": "Transaction owned by the REST adapter",
   "context": "The legacy opens the transaction after the validations (line 108) and commits at line 161. It rolls back at three points and each time rejects with a non-zero status (50005, 50006, 50007).",
   "decision": "The REST adapter owns the transaction around PayOrder. Any business error rejects the request and undoes everything. There are no savepoints, so no UnitOfWork port is declared.",
   "consequences": "The first debit is undone if the commission debit or the order update fails. The debit gateway must take part in the same transaction as the order update."
  },
  {
   "title": "Migration of data and port for sp_debito",
   "context": "The four tables live in different legacy databases (db_pagos, db_admin, db_cuentas). The account debit is done by the external procedure db_cuentas..sp_debito.",
   "decision": "The tables move to the target database with target names. sp_debito is behind the DebitGateway port, which returns the movement sequence and the return status (reserved name 'return'). The target treats a non-zero status as a failed debit.",
   "consequences": "The gateway adapter must debit within the same transactional context as the service. Otherwise a rollback would not undo the first debit."
  },
  {
   "title": "Missing rows reproduce legacy NULL semantics",
   "context": "In the legacy, a missing account row leaves @w_saldo NULL. The funds comparison is then not true, so the payment goes on to the debit. A missing tariff becomes 0, and a missing service row leaves the separate-charge flag unset, which behaves like 'N'.",
   "decision": "If the account is not found, the funds check is skipped. If neither tariff is found, the tariff is 0 and the commission is added to the total as when the flag is 'N'.",
   "consequences": "An unknown account is not rejected with INSUFFICIENT_FUNDS. Rejection is left to sp_debito (DEBIT_FAILED)."
  },
  {
   "title": "Monetary arithmetic",
   "context": "The legacy uses money, with 4 decimals. The WEB commission is round(tariff/2, 2).",
   "decision": "Use BigDecimal with scale 4 and rounding HALF_UP (away from zero) for the commission. The overdraft margin is 100.00 for non-VIR accounts.",
   "consequences": "The results are intended to match the legacy for the golden-master cases (e.g. 5.01/2 gives 2.51)."
  },
  {
   "title": "Error logging is not translated",
   "context": "The legacy calls cobis..sp_cerror at its ERROR label and returns the error code.",
   "decision": "sp_cerror is infrastructure and is replaced by exceptions and the framework's error handling. The message of each business error is returned in the rejection.",
   "consequences": "No error is logged in the cobis error tables from the new service."
  }
 ],
 "masks": [
  {
   "path": "outputs:@o_movimiento",
   "when": "rejected",
   "reason": "When the commission debit or the order update fails, the legacy returns the movement of the first debit even though it rolled it back. The target rejects the request with no outputs, because the movement no longer exists after the rollback."
  }
 ],
 "infrastructure": [
  "cobis..sp_cerror"
 ],
 "data_strategy": "migration"
}

Rules:
[
 {
  "id": "RULE-001",
  "name": "Account type must be CTE, AHO or VIR",
  "category": "validation",
  "priority": "P0",
  "statement": "A payment order is only accepted for account types CTE, AHO or VIR. Any other account type is rejected with error 50001 and the message 'TIPO DE CUENTA NO PERMITIDO'.",
  "condition": "@i_tipo_cuenta not in ('CTE', 'AHO', 'VIR')",
  "action": "Set @w_error = 50001 and @o_mensaje = 'TIPO DE CUENTA NO PERMITIDO'.",
  "inputs": [
   {
    "name": "@i_tipo_cuenta",
    "type": "text(fixed,3,iso8859-1)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "@w_error",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "@o_mensaje",
    "type": "text(var,120,iso8859-1)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Account type is allowed\n  Given the account type is 'AHO'\n  When the payment order is validated\n  Then no error is set for the account type",
   "Scenario: Account type is not allowed\n  Given the account type is 'PRE'\n  When the payment order is validated\n  Then the error code is 50001\n  And the message is 'TIPO DE CUENTA NO PERMITIDO'"
  ],
  "sources": [
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 34,
    "line_end": 37
   }
  ]
 },
 {
  "id": "RULE-002",
  "name": "Payment order must be pending to be paid",
  "category": "validation",
  "priority": "P0",
  "statement": "An order can only proceed when its status is 'P' (pending). Any other status is rejected with error 50003 and the message 'ORDEN NO ESTA PENDIENTE'.",
  "condition": "The status ord_estado of the order identified by @i_orden and @i_empresa in db_pagos..pg_orden is not 'P'.",
  "action": "Set @w_error = 50003 and @o_mensaje = 'ORDEN NO ESTA PENDIENTE'. The slice does not show what happens after the error is set.",
  "inputs": [
   {
    "name": "@i_orden",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "@i_empresa",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "ord_estado",
    "type": "text(fixed,1,iso8859-1)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "@w_error",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "@o_mensaje",
    "type": "text(var,120,iso8859-1)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Order is pending\n  Given order 100 of company 1 has status 'P'\n  When the payment procedure checks the order\n  Then no error is raised by this check",
   "Scenario: Order is not pending\n  Given order 100 of company 1 has status 'X'\n  When the payment procedure checks the order\n  Then @w_error is 50003\n  And @o_mensaje is 'ORDEN NO ESTA PENDIENTE'"
  ],
  "sources": [
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 42,
    "line_end": 45
   },
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 54,
    "line_end": 54
   },
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 56,
    "line_end": 57
   }
  ]
 },
 {
  "id": "RULE-003",
  "name": "Payment rejected when order does not exist",
  "category": "validation",
  "priority": "P0",
  "statement": "If the lookup of the order to be paid returns no rows, the payment is rejected with error code 50002 and the message 'ORDEN NO EXISTE'.",
  "condition": "@@rowcount = 0 after the preceding order lookup",
  "action": "Set @w_error = 50002 and @o_mensaje = 'ORDEN NO EXISTE'",
  "inputs": [
   {
    "name": "@@rowcount",
    "type": "integer(32,signed)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "@w_error",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "@o_mensaje",
    "type": "text(var,120,iso8859-1)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Order not found\n  Given the lookup of the order to pay returns 0 rows\n  When the payment procedure evaluates the result\n  Then the error code is 50002\n  And the message is 'ORDEN NO EXISTE'",
   "Scenario: Order found\n  Given the lookup of the order to pay returns 1 row\n  When the payment procedure evaluates the result\n  Then error 50002 is not set by this check"
  ],
  "sources": [
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 47,
    "line_end": 50
   }
  ]
 },
 {
  "id": "RULE-004",
  "name": "Commission tariff lookup: company-specific tariff overrides service default",
  "category": "calculation",
  "priority": "P0",
  "statement": "The base tariff for a payment is the one agreed for the company and service. If the company has no specific tariff for that service, the service's default tariff is used and the commission is not charged separately ('N'). If no tariff can be determined, it is zero.",
  "condition": "A row exists in ad_tarifa_empresa for tar_empresa = @i_empresa and tar_servicio = @i_servicio; otherwise use ad_servicio.srv_codigo = @i_servicio; if the resulting tariff is NULL.",
  "action": "With a company row: tariff = tar_valor and separate-charge flag = tar_separada. Without one (@@rowcount = 0): tariff = srv_tarifa and flag = 'N'. If the tariff is NULL it becomes 0.",
  "inputs": [
   {
    "name": "@i_empresa",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "@i_servicio",
    "type": "text(var,10,iso8859-1)",
    "description": ""
   },
   {
    "name": "tar_valor",
    "type": "decimal(19,4,signed)",
    "description": ""
   },
   {
    "name": "tar_separada",
    "type": "text(fixed,1,iso8859-1)",
    "description": ""
   },
   {
    "name": "srv_tarifa",
    "type": "decimal(19,4,signed)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "@w_tarifa",
    "type": "decimal(19,4,signed)",
    "description": ""
   },
   {
    "name": "@w_separada",
    "type": "text(fixed,1,iso8859-1)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Company tariff exists\nGiven company 10 has a tariff of 2.0000 with separate charge 'S' for service 'LUZ'\nWhen the tariff is resolved\nThen the tariff is 2.0000 and the separate-charge flag is 'S'",
   "Scenario: Fall back to service tariff\nGiven company 10 has no tariff row for service 'AGUA' and the service tariff is 1.5000\nWhen the tariff is resolved\nThen the tariff is 1.5000 and the separate-charge flag is 'N'",
   "Scenario: No tariff defined\nGiven the resolved tariff is NULL\nWhen the tariff is resolved\nThen the tariff is 0"
  ],
  "sources": [
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 62,
    "line_end": 66
   },
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 68,
    "line_end": 68
   },
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 70,
    "line_end": 72
   },
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 76,
    "line_end": 77
   }
  ]
 },
 {
  "id": "RULE-005",
  "name": "Comisión por canal y servicio NOMINA",
  "category": "calculation",
  "priority": "P0",
  "statement": "The commission is half the tariff, rounded to 2 decimals, when the payment comes through the WEB channel. Any other channel pays the full tariff. Service 'NOMINA' never carries a commission.",
  "condition": "@i_canal = 'WEB' gives half the tariff. Any other channel gives the full tariff. @i_servicio = 'NOMINA' overrides both.",
  "action": "@w_comision = round(@w_tarifa / 2, 2) if @i_canal = 'WEB', otherwise @w_comision = @w_tarifa. Then if @i_servicio = 'NOMINA', @w_comision = 0.",
  "inputs": [
   {
    "name": "@i_canal",
    "type": "text(fixed,3,iso8859-1)",
    "description": ""
