    private sealed class Fixture
    {
        public readonly List<string> Log = new();
        public readonly FakeOrders Orders;
        public readonly FakeTariffs Tariffs;
        public readonly FakeServices Services;
        public readonly FakeAccounts Accounts;
        public readonly FakeDebits Debits;

        public Fixture()
        {
            Orders = new FakeOrders(Log);
            Tariffs = new FakeTariffs(Log);
            Services = new FakeServices(Log);
            Accounts = new FakeAccounts(Log);
            Debits = new FakeDebits(Log);
        }

        public PayOrderService Service() => new(Orders, Tariffs, Services, Accounts, Debits);

        public PayOrderResponse Run(PayOrderRequest request) => Service().Execute(request);

        public BusinessError RunError(PayOrderRequest request) =>
            Assert.Throws<BusinessError>(() => Service().Execute(request));

        public void CompanyTariff(decimal? value, string? separate) =>
            Tariffs.Row = new CompanyTariff(1, "AGUA", value, separate);

        public void ServiceTariff(decimal? value) =>
            Services.Row = new ServiceCatalog("AGUA", value);
    }

    private static PayOrderRequest Req(
        string? serviceCode = "AGUA",
        string? accountType = "AHO",
        decimal? amount = 100.00m,
        string? channel = "VEN",
        int? orderNumber = 100,
        int? companyId = 1,
        DateTime? processDate = null,
        string? accountNumber = "1234567890") =>
        new(orderNumber, companyId, serviceCode, accountType, accountNumber, amount, channel, processDate ?? DefaultProcessDate);

    private static void AssertAmount(decimal expected, decimal? actual)
    {
        Assert.NotNull(actual);
        Assert.Equal(expected, actual!.Value);
    }

    private static void AssertError(BusinessError error, string code, string legacyCode, string message)
    {
        Assert.Equal(code, error.Code);
        Assert.Equal(legacyCode, error.LegacyCode);
        Assert.Equal(message, error.Message);
    }

    private static void AssertNothingWritten(Fixture fx)
    {
        Assert.Empty(fx.Debits.Calls);
        Assert.Empty(fx.Orders.Paid);
    }

