// src/App/Application/PayOrderService.cs
using Bank.Payments.Adapters.In.Rest;
using Bank.Payments.Domain.Error;
using Bank.Payments.Domain.Port;

namespace Bank.Payments.Application;

/// <summary>Application service of PayOrder (legacy dbo.sp_pago_orden).</summary>
public sealed class PayOrderService(
    OrderRepository orders,
    CompanyTariffRepository companyTariffs,
    ServiceRepository services,
    AccountRepository accounts,
    DebitGateway debits)
{
    public PayOrderResponse Execute(PayOrderRequest request)
    {
        // Legacy parameter default: @i_canal = 'WEB'.
        var channel = request.Channel ?? "WEB";

        // Legacy CHAR comparisons ignore trailing spaces; a NULL comparison is UNKNOWN (never true).
        var accountType = request.AccountType?.TrimEnd();

        // RULE-001: NULL not in (...) is UNKNOWN, so a NULL type is not rejected.
        if (accountType != null && accountType != "CTE" && accountType != "AHO" && accountType != "VIR")
        {
            throw new BusinessError("ACCOUNT_TYPE_NOT_ALLOWED", "50001", "TIPO DE CUENTA NO PERMITIDO");
        }

        // RULE-003 / RULE-002
        var order = orders.FindByNumberAndCompany(request.OrderNumber, request.CompanyId);
        if (order == null)
        {
            throw new BusinessError("ORDER_NOT_FOUND", "50002", "ORDEN NO EXISTE");
        }

        var status = order.Status?.TrimEnd();
        if (status != null && status != "P")
        {
            throw new BusinessError("ORDER_NOT_PENDING", "50003", "ORDEN NO ESTA PENDIENTE");
        }

        // RULE-004: tariff and separate-charge flag
        decimal? tariff = null;
        string? separate = null;
        var companyTariff = companyTariffs.FindByCompanyAndService(request.CompanyId, request.ServiceCode);
        if (companyTariff != null)
        {
            tariff = companyTariff.TariffValue;
            separate = companyTariff.SeparateCharge;
        }
        else
        {
            var service = services.FindByCode(request.ServiceCode);
            if (service != null)
            {
                tariff = service.DefaultTariff;
                separate = "N";
            }
        }

        if (tariff == null)
        {
            tariff = 0m;
        }

        // RULE-005: commission
        decimal commission;
        if (channel.TrimEnd() == "WEB")
        {
            commission = Math.Round(tariff.Value / 2m, 2, MidpointRounding.AwayFromZero);
        }
        else
        {
            commission = tariff.Value;
        }

        if (request.ServiceCode?.TrimEnd() == "NOMINA")
        {
            commission = 0m;
        }

        // RULE-006: total to debit
        decimal? total;
        if (separate?.TrimEnd() == "S")
        {
            total = request.Amount;
        }
        else
        {
            total = request.Amount + commission;
        }

        // RULE-007: funds check (NULL balance / total / type make the comparison UNKNOWN)
        var account = accounts.FindByNumberAndType(request.AccountNumber, request.AccountType);
        decimal? balance = account?.Balance;

        var isVir = accountType == "VIR";
        var isNotVir = accountType != null && accountType != "VIR";
        if ((isVir && balance < total) || (isNotVir && balance + 100.00m < total))
        {
            throw new BusinessError("INSUFFICIENT_FUNDS", "50004", "FONDOS INSUFICIENTES");
        }

        // RULE-008: debit of the total
        var firstDebit = debits.Debit(request.AccountNumber, request.AccountType, total, "PAGO ORDEN");
        if (firstDebit == null || firstDebit.ReturnCode != 0)
        {
            throw new BusinessError("DEBIT_FAILED", "50005", "ERROR EN DEBITO");
        }

        var movement = firstDebit.Movement;

        // RULE-009 / RULE-010: separate commission debit
        if (separate?.TrimEnd() == "S" && commission > 0m)
        {
            var commissionDebit = debits.Debit(request.AccountNumber, request.AccountType, commission, "COMISION PAGO");
            if (commissionDebit == null || commissionDebit.ReturnCode != 0)
            {
                throw new BusinessError("COMMISSION_FAILED", "50006", "ERROR EN COMISION");
            }
        }

        // RULE-011 / RULE-012: mark the order as paid
        var rows = orders.MarkPaid(request.OrderNumber, request.CompanyId, "A", request.ProcessDate, commission);
        if (rows == 0)
        {
            throw new BusinessError("ORDER_UPDATE_FAILED", "50007", "ERROR ACTUALIZANDO ORDEN");
        }

        // RULE-013
        return new PayOrderResponse(movement, "PAGO REALIZADO");
    }
}
